{
  "findings": [
    {
      "check_id": "CKV_AWS_204",
      "title": "AMI block device encryption is not enabled",
      "resource": "aws_ami.pass",
      "severity": "HIGH",
      "explanation": "The /dev/xvda1 EBS block device does not explicitly enable encryption, which may expose data stored in the AMI snapshot at rest."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
    encrypted   = true
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }
}
",
  "fix_summary": "Enabled encryption for the /dev/xvda1 EBS block device. The existing encrypted configuration for /dev/xvda2 was preserved."
}
